package api_test

import (
	"fmt"
	"net/http"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// An object of another organization is answered like an unknown one: the same status and body.
func TestInvoiceLinesOfAnotherOrg(t *testing.T) {
	e := apitest.New(t)
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	var inv store.Invoice
	e.MustDo(http.StatusCreated, "POST", "/v1/invoices", e.Acme.Key, map[string]any{"customer_id": c.ID, "currency": "USD",
		"lines": []map[string]any{{"description": "Consulting", "quantity": 1, "unit_amount": 100}}}, &inv)

	foreign := e.Do("GET", "/v1/invoices/"+inv.ID+"/lines", e.Globex.Key, nil)
	unknown := e.Do("GET", "/v1/invoices/in_000000/lines", e.Globex.Key, nil)
	if foreign.Code != http.StatusNotFound || foreign.Map(t)["error"] != "not_found" {
		t.Fatalf("another organization's invoice lines: %s", foreign)
	}
	if foreign.Code != unknown.Code || string(foreign.Body) != string(unknown.Body) {
		t.Fatalf("another organization's invoice answered %s, an unknown one %s", foreign, unknown)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invoices/"+inv.ID+"/lines", e.Acme.Key, nil, nil)
}

// A customer_id of another organization, named in the body, is answered like an unknown customer_id.
func TestCustomerIDOfAnotherOrg(t *testing.T) {
	e := apitest.New(t)
	acme := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	plan := e.CreatePlan(e.Globex, "Pro", "EUR", "10.00")

	bodies := map[string]func(customerID string) (string, map[string]any){
		"invoice": func(customerID string) (string, map[string]any) {
			return "/v1/invoices", map[string]any{"customer_id": customerID, "currency": "EUR",
				"lines": []map[string]any{{"description": "Consulting", "quantity": 1, "unit_amount": 100}}}
		},
		"subscription": func(customerID string) (string, map[string]any) {
			return "/v1/subscriptions", map[string]any{"customer_id": customerID, "plan_id": plan.ID}
		},
	}
	for kind, body := range bodies {
		path, unknownBody := body("cus_000000")
		unknown := e.Do("POST", path, e.Globex.Key, unknownBody)
		path, foreignBody := body(acme.ID)
		foreign := e.Do("POST", path, e.Globex.Key, foreignBody)
		if foreign.Code != http.StatusNotFound || foreign.Map(t)["error"] != "not_found" {
			t.Fatalf("%s with another organization's customer: %s", kind, foreign)
		}
		if foreign.Code != unknown.Code || string(foreign.Body) != string(unknown.Body) {
			t.Fatalf("%s: another organization's customer answered %s, an unknown one %s", kind, foreign, unknown)
		}
	}
	if n := len(e.Store.ListInvoices(e.Globex.ID, store.InvoiceFilter{})); n != 0 {
		t.Fatalf("Globex has %d invoices", n)
	}
	if n := len(e.Store.Subscriptions(e.Globex.ID, store.SubscriptionFilter{})); n != 0 {
		t.Fatalf("Globex has %d subscriptions", n)
	}
}

// An endpoint of another organization cannot be deleted; the owner's endpoint is unchanged.
func TestWebhookEndpointOfAnotherOrg(t *testing.T) {
	e := apitest.New(t)
	var ep store.WebhookEndpoint
	e.MustDo(http.StatusCreated, "POST", "/v1/webhook-endpoints", e.Acme.Key, map[string]any{"url": "https://hooks.acme.example/tally", "events": []string{"*"}}, &ep)
	if r := e.Do("DELETE", "/v1/webhook-endpoints/"+ep.ID, e.Globex.Key, nil); r.Code != http.StatusNotFound || r.Map(t)["error"] != "not_found" {
		t.Fatalf("delete another organization's endpoint: %s", r)
	}
	e.MustDo(http.StatusOK, "GET", "/v1/webhook-endpoints/"+ep.ID, e.Acme.Key, nil, nil)
}

// Customers are unique per organization by email address: two organizations can each have one, and neither sees the
// other's.
func TestEmailsAreScopedToOrganization(t *testing.T) {
	e := apitest.New(t)
