	var events struct{ Items []store.Event }
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.created", e.Acme.Key, nil, &events)
	key, _ := e.Store.APIKeyByToken(e.Acme.Key)
	chargesBefore := len(e.Gateway.Charges())

	probes := []struct{ method, path string; body any }{
		{"GET", "/v1/customers/" + c.ID, nil},
		{"PATCH", "/v1/customers/" + c.ID, map[string]string{"name": "Changed"}},
		{"DELETE", "/v1/customers/" + c.ID, nil},
		{"GET", "/v1/plans/" + p.ID, nil},
		{"PATCH", "/v1/plans/" + p.ID, map[string]string{"name": "Changed"}},
		{"GET", "/v1/subscriptions/" + sub.ID, nil},
		{"PATCH", "/v1/subscriptions/" + sub.ID, map[string]any{"quantity": 5}},
		{"POST", "/v1/subscriptions/" + sub.ID + "/cancel", nil},
		{"POST", "/v1/subscriptions/" + sub.ID + "/usage", map[string]int64{"quantity": 1}},
		{"GET", "/v1/invoices/" + inv.ID, nil},
		{"GET", "/v1/invoices/" + inv.ID + "/lines", nil},
		{"POST", "/v1/invoices/" + inv.ID + "/pay", map[string]string{"payment_method": "pm_card_visa"}},
		{"POST", "/v1/invoices/" + inv.ID + "/void", nil},
		{"GET", "/v1/webhook-endpoints/" + ep.ID, nil},
