package store

import (
	"errors"
	"testing"

	"example.com/tally/internal/money"
)

// Two organizations can each have a customer with the same email address, and neither finds or changes the other's.
func TestCustomerEmailsArePerOrg(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	ca, err := s.CreateCustomer(a.ID, "Jane A", "jane@example.com", t0)
	if err != nil {
		t.Fatal(err)
	}
	cb, err := s.CreateCustomer(b.ID, "Jane B", "Jane@Example.com", t0)
	if err != nil {
		t.Fatalf("the same email in another org: %v", err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != ca.ID {
		t.Fatalf("org A finds %+v, want %s", got, ca.ID)
	}
	if got, ok := s.FindCustomerByEmail(b.ID, "jane@example.com"); !ok || got.ID != cb.ID {
		t.Fatalf("org B finds %+v, want %s", got, cb.ID)
	}

	// Deleting B's customer leaves A's email entry alone.
	if err := s.DeleteCustomer(b.ID, cb.ID); err != nil {
		t.Fatal(err)
	}
	if got, ok := s.FindCustomerByEmail(a.ID, "jane@example.com"); !ok || got.ID != ca.ID {
		t.Fatalf("after B deleted its customer, org A finds %+v", got)
	}
	if _, ok := s.FindCustomerByEmail(b.ID, "jane@example.com"); ok {
		t.Fatal("org B finds a deleted customer")
	}
}

// A subscription or invoice that names another organization's customer is ErrNotFound, as an unknown customer is.
func TestCustomerOfAnotherOrgIsNotFound(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	ca, err := s.CreateCustomer(a.ID, "Jane", "jane@example.com", t0)
	if err != nil {
		t.Fatal(err)
	}
	plan, err := s.CreatePlan(Plan{OrgID: b.ID, Name: "Pro", Currency: money.USD, UnitAmount: 1000, Interval: Monthly}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateSubscription(Subscription{OrgID: b.ID, CustomerID: ca.ID, PlanID: plan.ID, Quantity: 1, Status: Active}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("subscription for another org's customer: %v", err)
	}
	if _, err := s.CreateInvoice(Invoice{OrgID: b.ID, CustomerID: ca.ID, Currency: money.USD, Lines: []Line{{Description: "x", Quantity: 1, UnitAmount: 1}}}, t0); !errors.Is(err, ErrNotFound) {
		t.Fatalf("invoice for another org's customer: %v", err)
	}
	if n := len(s.Subscriptions(b.ID, SubscriptionFilter{})) + len(s.ListInvoices(b.ID, InvoiceFilter{})); n != 0 {
		t.Fatalf("org B got %d objects", n)
	}
}

// An endpoint is deleted only by its own organization.
func TestDeleteOrgWebhookEndpoint(t *testing.T) {
	s := New()
	a, b := newOrg(t, s, "A"), newOrg(t, s, "B")
	ep, err := s.CreateWebhookEndpoint(WebhookEndpoint{OrgID: a.ID, URL: "https://hooks.example/a", Events: []string{"*"}, Enabled: true}, t0)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.DeleteOrgWebhookEndpoint(b.ID, ep.ID); !errors.Is(err, ErrNotFound) {
		t.Fatalf("delete from another org: %v", err)
	}
	if _, ok := s.WebhookEndpoint(a.ID, ep.ID); !ok {
		t.Fatal("another org's delete removed the endpoint")
	}
	if err := s.DeleteOrgWebhookEndpoint(a.ID, ep.ID); err != nil {
		t.Fatal(err)
	}
	if _, ok := s.WebhookEndpoint(a.ID, ep.ID); ok {
		t.Fatal("endpoint still there after its org deleted it")
	}
}

